const isWailsDraggable = (el: HTMLElement | null): boolean => {
    let cur = el
    while (cur) {
        const val = getComputedStyle(cur).getPropertyValue('--wails-draggable').trim()
        if (val === 'drag') return true
        if (val === 'no-drag') return false
        cur = cur.parentElement
    }
    return false
}

